    int resource;
public:
    // User-defined Copy Constructor (CC)
    MoveDeleted(const MoveDeleted& other)
        : resource(other.resource) {}

    // RESULT: Move Constructor (MC) and
    // Move Assignment Operator (MAO) are implicitly deleted.

