class MoveSuppressedByDestructor {
    // Defines Destructor (D)
    ~MoveSuppressedByDestructor() = default;

    // RESULT: If D is defined, MC and MAO are only generated
    // if CAO/CC are implicitly generated or defaulted.
    // Generally, D definition suppresses implicit generation.
};
